-- بوابة أَثَر — «مِعيار — من أَثَر» م2-أ «بنك مِعيار الجديد» (2026-12-17)
-- 62 مقطعًا جديدًا (قراءة/استماع · الاستماع بصوت edge-tts من public/miaar/audio) + 384 بندًا جديدًا من «ما قبل A1» المصوّر إلى C2
-- بحالة in_review (تُعتمد من «مراجعة الدفعة» في /admin/miaar/bank) · 42 واصفًا للكتابة والمحادثة (→126)
-- + وسم البنك القديم miaar-legacy (واصف مقترح · علم التكرار) دون تغيير حالته حتى لا يتوقّف الاختبار الحيّ
-- + مخطّطات C1/C2 (36 بندًا/50 دقيقة) و«أرضية ما قبل A1». آمن لإعادة التنفيذ.

-- 1) أعمدة جديدة
alter table public.miaar_passages add column if not exists meta jsonb;
alter table public.question_bank_items add column if not exists author_notes jsonb;
alter table public.question_bank_items drop constraint if exists question_bank_items_item_type_check;
alter table public.question_bank_items add constraint question_bank_items_item_type_check check (item_type in ('mcq','picture_choice','picture_label','picture_sequence','true_false_notgiven','cloze_bank','matching','ordering','word_tap','short_dictation'));
create index if not exists question_bank_items_batch_idx on public.question_bank_items(import_batch_id);

