-- 7) البنك القديم: وسم miaar-legacy + واصف مقترح + علم التكرار (الحالة لا تتغيّر — الاختبار الحيّ يستمر حتى تكتمل المراجعة)
update public.question_bank_items set legacy_extra = coalesce(legacy_extra, '{}'::jsonb) || jsonb_build_object('batch', 'miaar-legacy', 'review_flag', 'legacy_recheck')
where content_version <> 'athar-m2a' and coalesce(legacy_extra->>'batch', '') <> 'miaar-legacy';
update public.question_bank_items i set descriptor_code = d.code
from public.miaar_descriptors d
where i.content_version <> 'athar-m2a' and i.descriptor_code is null
  and d.level = i.level and d.code = (case i.skill when 'reading' then 'RD-' when 'listening' then 'LI-' else 'LU-' end) || i.level || '-01';
with n as (
  select id, item_code, content_version, regexp_replace(lower(question_text), '[\sً-ْـ،؛:.؟!«»"]+', '', 'g') as norm from public.question_bank_items
), dup as (
  select a.id, b.item_code as dup_of from n a join n b on a.norm = b.norm and a.id <> b.id and length(a.norm) > 12
  and (b.content_version = 'athar-m2a' or b.item_code < a.item_code)
)
update public.question_bank_items i set legacy_extra = coalesce(i.legacy_extra, '{}'::jsonb) || jsonb_build_object('duplicate_of', dup.dup_of)
from (select id, min(dup_of) as dup_of from dup group by id) dup where dup.id = i.id and i.content_version <> 'athar-m2a';

-- 8) المخطّطات: C1/C2 36 بندًا في 50 دقيقة · أرضية ما قبل A1
update public.question_bank_blueprints set requirements = '{"C1":{"grammar_vocab":12,"reading":12,"listening":12}}'::jsonb, duration_minutes = 50, description_ar = 'نموذج ثابت لمستوى C1: 36 بندًا (قراءة 12 · استماع 12 · كفاية لغوية 12) في 50 دقيقة؛ حدّ القطع الافتراضي 60%.', updated_at = now() where code = 'level-c1-v1';
update public.question_bank_blueprints set requirements = '{"C2":{"grammar_vocab":12,"reading":12,"listening":12}}'::jsonb, duration_minutes = 50, description_ar = 'نموذج ثابت لمستوى C2: 36 بندًا (قراءة 12 · استماع 12 · كفاية لغوية 12) في 50 دقيقة؛ حدّ القطع الافتراضي 60%.', updated_at = now() where code = 'level-c2-v1';
