-- 9) التحقق (المتوقّع: items_m2a = 384 · keys_m2a = 384 · in_review_m2a = 384 · passages_m2a = 62 · listening_audio = 36 · descriptors = 126 · pre_a1_items = 36 · blueprints = 10 · batch = 1 · legacy_flagged = عدد البنود القديمة كلّها (يُطبع) · legacy_dupes = يُطبع)
select
  (select count(*) from public.question_bank_items where content_version = 'athar-m2a') as items_m2a,
  (select count(*) from public.question_bank_answer_keys k join public.question_bank_items i on i.id = k.item_id where i.content_version = 'athar-m2a') as keys_m2a,
  (select count(*) from public.question_bank_items where content_version = 'athar-m2a' and status = 'in_review') as in_review_m2a,
  (select count(*) from public.miaar_passages where version = 'athar-m2a') as passages_m2a,
  (select count(*) from public.miaar_passages where version = 'athar-m2a' and skill = 'listening' and audio_public_path is not null) as listening_audio,
  (select count(*) from public.miaar_descriptors) as descriptors,
  (select count(*) from public.question_bank_items where content_version = 'athar-m2a' and level = 'PRE_A1') as pre_a1_items,
  (select count(*) from public.question_bank_blueprints) as blueprints,
  (select count(*) from public.question_bank_import_batches where id = '7a2b9c0e-0000-4000-8000-0000000002a1') as batch,
  (select count(*) from public.question_bank_items where legacy_extra->>'batch' = 'miaar-legacy') as legacy_flagged,
  (select count(*) from public.question_bank_items where legacy_extra ? 'duplicate_of') as legacy_dupes;
